import{z as t,x as o,o as E,c as B,q as r,j as n,D as e,d as s,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"内存调试","description":"","frontmatter":{"title":"内存调试","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/obs-memory-debugging.md","filePath":"cs/obs-memory-debugging.md","lastUpdated":1791063341000}'),d={name:"cs/obs-memory-debugging.md"};function c(m,a,p,h,S,C){const A=o("Mermaid");return E(),B("div",null,[a[2]||(a[2]=r('<h1 id="内存调试" tabindex="-1">内存调试 <a class="header-anchor" href="#内存调试" aria-label="Permalink to &quot;内存调试&quot;">​</a></h1><div class="epigraph"><p>内存错误的特点是第一现场与案发现场分离：溢出写在 A 处，崩溃爆在 B 处；调试的全部工作是让这两点重新接上因果。</p><footer>—— 据 Nethercote and Seward, Valgrind, PLDI 2007；Serebryany et al., AddressSanitizer, USENIX ATC 2012 整理</footer></div><p><a href="/cs/obs-flamegraphs">上一课</a>回答了「哪里慢」。本课回答「哪里坏了」。影子内存与红区的机制，<a href="/cs/asan-mechanism">ASan 的机制</a>已钉；<a href="/cs/heap-uaf">堆 UAF</a> 的形态、<a href="/cs/oom-killer">OOM killer</a> 的行为也各有专课。剩下的缺口是工作流：从一个症状出发——崩溃、静默损坏、内存持续增长——选哪个工具、付什么代价、能下什么结论、不能下什么结论。这是工具组的最后一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三类症状是三条路。其一，崩溃：段错误把进程打断，但栈回溯只告诉你崩在哪，不告诉你谁写的——越界写踩坏了别人的对象，崩在无辜的代码里，第一现场早已撤离。其二，静默损坏：未初始化读、use-after-free 读、数据竞争，程序不崩，输出偶尔错，复现概率像掷骰子。其三，内存增长：RSS 一路爬，是泄漏、是缓存驻留、还是分配器碎片，光看监控曲线分不开。每条路的检测器、开销与结论强度都不同，选错路浪费的是天而不是小时。</p><h3 id="按症状选工具" tabindex="-1">按症状选工具 <a class="header-anchor" href="#按症状选工具" aria-label="Permalink to &quot;按症状选工具&quot;">​</a></h3><p>崩溃路：core dump 加<a href="/cs/debugger-breakpoint">调试器与断点</a>回溯栈，<a href="/cs/dwarf-debug-info">DWARF</a> 给出行号；但这一步只回答「死在哪」。把「死在哪」升级成「谁干的」，要用 ASan 重跑：影子内存把检查提前到每一次访问，越界第一次发生就被拦下，第一现场与案发现场合一。静默损坏路：未初始化读找 MSan 或 Valgrind memcheck——后者不用重编译，代价是解释执行；use-after-free 靠 ASan 的隔离区延迟复用。增长路：先分型再动手——看<a href="/cs/anon-vs-file-page">匿名页对文件页</a>的构成，做堆分配剖析拿分配栈，对两个时间点的堆快照做差。</p>',7)),(E(),n(i,null,{default:e(()=>[l(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%7B%22%E7%97%87%E7%8A%B6%E6%98%AF%E5%93%AA%E7%B1%BB%22%7D%20--%3E%7C%22%E5%B4%A9%E6%BA%83%22%7C%20CORE%5B%22core%20%2B%20%E8%B0%83%E8%AF%95%E5%99%A8%E5%9B%9E%E6%BA%AF%22%5D%0A%20%20CORE%20--%3E%20REPRO%5B%22ASan%20%E9%87%8D%E8%B7%91%EF%BC%9A%E7%AC%AC%E4%B8%80%E7%8E%B0%E5%9C%BA%E5%8D%B3%E6%A1%88%E5%8F%91%22%5D%0A%20%20SYM%20--%3E%7C%22%E9%9D%99%E9%BB%98%E6%8D%9F%E5%9D%8F%22%7C%20QUIET%5B%22MSan%20%2F%20memcheck%20%2F%20%E9%9A%94%E7%A6%BB%E5%8C%BA%22%5D%0A%20%20SYM%20--%3E%7C%22%E5%86%85%E5%AD%98%E5%A2%9E%E9%95%BF%22%7C%20GROW%5B%22%E5%A0%86%E5%89%96%E6%9E%90%20%2B%20%E5%BF%AB%E7%85%A7%E5%B7%AE%E5%88%86%22%5D%0A%20%20GROW%20--%3E%20DECIDE%7B%22%E5%8F%AF%E8%BE%BE%E4%B8%94%E4%B8%8D%E9%87%8A%E6%94%BE%3F%22%7D%0A%20%20DECIDE%20--%3E%7C%22%E6%98%AF%22%7C%20LEAK%5B%22%E7%9C%9F%E6%B3%84%E6%BC%8F%EF%BC%9A%E6%89%BE%E5%88%86%E9%85%8D%E6%A0%88%22%5D%0A%20%20DECIDE%20--%3E%7C%22%E5%90%A6%22%7C%20RETAIN%5B%22%E9%A9%BB%E7%95%99%E6%88%96%E7%A2%8E%E7%89%87%EF%BC%9A%E6%94%B9%E7%BC%93%E5%AD%98%E4%B8%8E%E5%88%86%E9%85%8D%E7%AD%96%E7%95%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">Valgrind memcheck 的代价是解释执行：常见口径慢 10 到 50 倍。它能就地诊断一个不会崩的静默错误，但不该挂在持续运行的测试里过夜跑全量。</span></p><p><span class="marginnote">直觉类比：影子内存像小区门禁台账——每 8 字节真实内存在台账里有一格，登记着「谁能碰」；每次内存访问先查台账，红区就是登记成「禁止入内」的缓冲带，一撞就响，越界第一次发生就被拦下。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>全量插桩留给测试环境：ASan 约 2 倍 CPU 与约 2 倍内存的税（1/8 影子加每对象红区），换来「首次越界即报」的结论强度；CI 与压测里常开。生产环境反过来：采样型分配剖析——按分配抽样记栈——开销压到可常开，代价是小对象可能漏采；先用它定位可疑的分配点，再回测试环境用 ASan 定罪。增长路的关键判据：真泄漏是「不可达且不释放」——需要保留分配栈与调用图才能下结论；可达但不用是缓存驻留，要改淘汰策略；释放了但 RSS 不降是 <a href="/cs/brk-heap">brk 与堆</a>的碎片，罪在分配器不在业务。内核侧的内存压力先读 OOM 日志的进程账单（<a href="/cs/oom-killer">OOM killer</a> 口径），别在用户态瞎猜。</p><p><span class="marginnote">常见误区：初学者看到 RSS 曲线一路涨就断定「内存泄漏」。实际上分配器释放内存后常先攥在手里不还给操作系统（碎片、arena 都是原因），RSS 不降可能是缓存驻留或碎片；下「真泄漏」的结论要靠分配栈证明「不可达且不释放」。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么崩在哪不等于谁干的：内存是共享命名空间，踩踏的效果延迟显现，破坏者与受害者只在时间上相邻、在因果上很远。检测器的共同思路是把检查点前移到访问时刻——影子内存一次查表判读写合法性，红区把越界变成确定性的撞墙——于是第一次错误就是最后一次机会。为什么 MSan 与数据竞争检测要求全量重编译：半插桩的程序里，未经标注的值会被当作干净传播，漏报比崩溃更危险；工具链的边界就是结论的边界。为什么泄漏难下定义：分配器不向操作系统归还内存是常态（arena、对齐、碎片），RSS 涨不等于泄漏；判据必须落在「不可达且不释放」上，而判定不可达需要调用图。这也是堆剖析比「看 RSS 曲线」强的原因。</p><p><span class="marginnote">数字实例：影子内存按 1/8 记账——每 8 字节真实内存对应 1 字节影子。一个 1 GB 的堆就要额外约 128 MB 影子，再加上每件对象两侧的红区与元数据，合计就是「约 2 倍内存」这笔税的来历。</span></p>',8)),(E(),n(i,null,{default:e(()=>[l(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%A8%8B%E5%BA%8F%E8%AE%BF%E9%97%AE%E5%9C%B0%E5%9D%80%20A%22%5D%20--%3E%20S%5B%22%E6%9F%A5%20A%20%E7%9A%84%E5%BD%B1%E5%AD%90%E5%AD%97%E8%8A%82%22%5D%0A%20%20S%20--%3E%7C%22%E6%A0%87%E8%AE%B0%E5%8F%AF%E5%86%99%22%7C%20OK%5B%22%E6%94%BE%E8%A1%8C%22%5D%0A%20%20S%20--%3E%7C%22%E8%90%BD%E5%9C%A8%E7%BA%A2%E5%8C%BA%22%7C%20T%5B%22%E7%AB%8B%E5%8D%B3%E6%8A%A5%E9%94%99%20%E9%A6%96%E9%94%99%E5%8D%B3%E7%8E%B0%22%5D%0A%20%20S%20--%3E%7C%22%E5%B7%B2%E9%87%8A%E6%94%BE%E4%B8%94%E5%9C%A8%E9%9A%94%E7%A6%BB%E5%8C%BA%22%7C%20U%5B%22%E6%8A%A5%20use-after-free%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重讲影子内存的位级设计——那是 ASan 机制课的；不展开并发错误的检测，数据竞争有自己的工具与理论，混讲会稀释两边。检测器给出的是证据强度不同的话：memcheck 的未初始化报告可靠，采样剖析只是线索。长期解是把这类错误类整体消灭——<a href="/cs/memory-safe-languages">内存安全语言迁移</a>改变的是错误分布，不是调试技巧。工具组五课到此收口：下一课进工程单元，把观测从单机搬到跨服务，从「这台机器」到「这次请求的一生」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三症状三路：崩溃找第一现场，静默损坏靠插桩或解释执行，增长先分型。</li><li>崩溃栈只答「死在哪」；ASan 把检查前移到访问点，让首错即现。</li><li>泄漏的判据是「不可达且不释放」；RSS 涨可能是驻留或碎片。</li><li>测试环境全量插桩，生产环境采样剖析，结论强度与开销配套。</li><li>检测器要求全量重编译时，半插桩的漏报不可信。</li><li>出处：Valgrind（PLDI 2007）；ASan（USENIX ATC 2012）；主干课 ASan 机制、OOM killer 的口径。</li></ul>',4))])}const _=t(d,[["render",c]]);export{f as __pageData,_ as default};
